16	export default function Error({
17	  error,
18	  reset,
19	}: {
20	  error: Error & { digest?: string };
21	  reset: () => void;
22	}) {
23	  React.useEffect(() => {
24	    // Surface the error for diagnostics without leaking details to the UI.
25	    console.error(error);
26	  }, [error]);
27	
