29	    <Container as="main" id="main" className="flex-1 py-12 max-md:py-8">
30	      <Card role="alert" className="mx-auto flex max-w-xl flex-col items-start gap-4">
31	        <span className="flex items-center gap-2 text-alert">
32	          <TriangleAlert size={24} strokeWidth={2} aria-hidden="true" />
